        let args = try JSONEncoder().encode(SetDepthArgs(doc: doc, block: block, depth: depth))
        _ = try await transport.execute(method: "set_depth", argsJSON: args)
    }

    /// set_kind
    ///
    /// Changes a block's type.
    ///
    /// Write (`mutating`): sent with `execute`.
    ///
    /// - Parameters:
    ///   - doc: The document id.
    ///   - block: The block id.
    ///   - kind: The new block type, as for `insert_block`.
    public func setKind(doc: String, block: String, kind: String) async throws {
        let args = try JSONEncoder().encode(SetKindArgs(doc: doc, block: block, kind: kind))
        _ = try await transport.execute(method: "set_kind", argsJSON: args)
    }

    /// split_block
    ///
    /// Splits a block in two at a text position and returns the new block, which holds the text after the split and follows the original.
    /// Not idempotent: a retry after a lost response splits again, so read the blocks before repeating.
    /// Positions count Unicode scalar values, not bytes or UTF-16 units.
    ///
    /// Write (`mutating`): sent with `execute`.
    ///
    /// - Parameters:
    ///   - doc: The document id.
    ///   - block: The block to split.
    ///   - at: The position to split at; the text from here on moves to the new block.
    /// - Returns: The new block's id.
    @discardableResult
    public func splitBlock(doc: String, block: String, at: UInt32) async throws -> String {
        let args = try JSONEncoder().encode(SplitBlockArgs(doc: doc, block: block, at: at))
        let response = try await transport.execute(method: "split_block", argsJSON: args)
        return try JSONDecoder().decode(String.self, from: response)
    }

    /// title_anchor_at
    ///
    /// Returns a cursor for the gap at a title position, as an opaque token that survives concurrent edits and that any member can resolve.
    /// Positions count Unicode scalar values, not bytes or UTF-16 units.
    ///
    /// View (`read_only`): sent with `query`.
    ///
    /// - Parameters:
    ///   - doc: The document id.
    ///   - position: The gap, counted from 0 at the start of the title.
    ///   - before: Which side the anchor leans toward when text is inserted exactly at the gap.
    /// - Returns: An opaque anchor token.
    public func titleAnchorAt(doc: String, position: UInt32, before: Bool) async throws -> String {
        let args = try JSONEncoder().encode(TitleAnchorAtArgs(doc: doc, position: position, before: before))
        let response = try await transport.query(method: "title_anchor_at", argsJSON: args)
        return try JSONDecoder().decode(String.self, from: response)
    }

    /// title_apply_delta
    ///
    /// Applies one editing transaction to a document's title and returns a token that `title_undo` takes.
    /// `ops` is a list of steps that walk the text as it was before the change: `{"retain": 3, "attributes": null}` keeps three characters, `{"insert": "text", "attributes": null}` adds text, `{"delete": 2}` removes two.
    /// Text after the last step is kept.
    /// The title carries no formatting, so a step with non-null `attributes` is refused.
    /// A transaction that leaves the title longer than 1024 characters is refused.
    /// Positions count Unicode scalar values, not bytes or UTF-16 units.
    ///
    /// Write (`mutating`): sent with `execute`.
    ///
    /// - Parameters:
    ///   - doc: The document id.
    ///   - ops: The steps of the transaction, in order.
    /// - Returns: An opaque undo token.
    @discardableResult
    public func titleApplyDelta(doc: String, ops: [Change]) async throws -> String {
        let args = try JSONEncoder().encode(TitleApplyDeltaArgs(doc: doc, ops: ops))
        let response = try await transport.execute(method: "title_apply_delta", argsJSON: args)
        return try JSONDecoder().decode(String.self, from: response)
    }

    /// title_apply_delta_on
    ///
    /// Like `title_apply_delta`, but only applies when the title is still exactly `base`, because a position counted in any other text names the wrong place.
    /// When `anchor` is given the write must also be an insert right where that anchor sits.
    /// On refusal nothing is written: `applied` is `false` and `text` is the current title to rebase onto.
    ///
    /// Write (`mutating`): sent with `execute`.
    ///
    /// - Parameters:
    ///   - doc: The document id.
    ///   - base: The full title text the steps were computed against.
    ///   - ops: The steps of the transaction, as for `title_apply_delta`.
    ///   - anchor: Optional cursor token from `title_anchor_at`; `null` for an unanchored write.
    /// - Returns: Whether the write applied, the undo token, the resulting title, and an anchor at the end of the edit.
    @discardableResult
    public func titleApplyDeltaOn(doc: String, base: String, ops: [Change], anchor: String? = nil) async throws -> TitleApplied {
        let args = try JSONEncoder().encode(TitleApplyDeltaOnArgs(doc: doc, base: base, ops: ops, anchor: anchor))
        let response = try await transport.execute(method: "title_apply_delta_on", argsJSON: args)
        return try JSONDecoder().decode(TitleApplied.self, from: response)
    }

    /// title_resolve
    ///
    /// Returns where anchors currently sit in this node's copy of the title.
    ///
    /// View (`read_only`): sent with `query`.
    ///
    /// - Parameters:
    ///   - doc: The document id.
    ///   - anchors: Tokens from `title_anchor_at`.
    /// - Returns: One position per anchor, in order; `null` for an anchor this node cannot place yet.
    public func titleResolve(doc: String, anchors: [String]) async throws -> [UInt32] {
        let args = try JSONEncoder().encode(TitleResolveArgs(doc: doc, anchors: anchors))
        let response = try await transport.query(method: "title_resolve", argsJSON: args)
        return try JSONDecoder().decode([UInt32].self, from: response)
    }

    /// title_undo
    ///
    /// Takes a whole title transaction back and returns a token that redoes it.
    ///
    /// Write (`mutating`): sent with `execute`.
    ///
    /// - Parameters:
    ///   - doc: The document id.
    ///   - token: The token `title_apply_delta` (or a previous undo) returned.
    /// - Returns: An opaque token that redoes the transaction.
    @discardableResult
    public func titleUndo(doc: String, token: String) async throws -> String {
        let args = try JSONEncoder().encode(TitleUndoArgs(doc: doc, token: token))
        let response = try await transport.execute(method: "title_undo", argsJSON: args)
        return try JSONDecoder().decode(String.self, from: response)
    }

    /// unarchive_doc
    ///
    /// Restores an archived document to the default `list_docs` view.
    ///
    /// Write (`mutating`): sent with `execute`.
    ///
    /// - Parameters:
    ///   - id: The document id.
    public func unarchiveDoc(id: String) async throws {
        let args = try JSONEncoder().encode(UnarchiveDocArgs(id: id))
        _ = try await transport.execute(method: "unarchive_doc", argsJSON: args)
    }

    /// undo
    ///
    /// Takes a whole text transaction back and returns a token that redoes it.
    ///
    /// Write (`mutating`): sent with `execute`.
    ///
    /// - Parameters:
    ///   - doc: The document id.
    ///   - block: The block the transaction was applied to.
    ///   - token: The token `apply_delta` (or a previous undo) returned.
    /// - Returns: An opaque token that redoes the transaction.
    @discardableResult
    public func undo(doc: String, block: String, token: String) async throws -> String {
        let args = try JSONEncoder().encode(UndoArgs(doc: doc, block: block, token: token))
        let response = try await transport.execute(method: "undo", argsJSON: args)
        return try JSONDecoder().decode(String.self, from: response)
    }

