// MARK: - Types

/// What `apply_delta_on` did. The block's spans come back either way, so a
/// refused write hands the client exactly the state it has to rebase onto.
public struct Applied: Codable, Sendable, Equatable {
    /// `true` when the steps were written, `false` when the write was refused.
    public var applied: Bool
    /// The undo token for `undo`; `null` on a refusal.
    public var token: String?
    /// The block's spans after the write, or the current ones on a refusal.
    public var spans: [Span]
    /// The gap after this write's last change, or on a refusal the anchor sent.
    public var anchor: String?
    /// Where `anchor` sits in `spans`.
    public var anchorPos: UInt32?
    /// The id of each character of `spans`, so a refused write rebases by identity.
    public var ids: [Run]

    public init(applied: Bool, token: String? = nil, spans: [Span], anchor: String? = nil, anchorPos: UInt32? = nil, ids: [Run]) {
        self.applied = applied
        self.token = token
        self.spans = spans
        self.anchor = anchor
        self.anchorPos = anchorPos
        self.ids = ids
    }

    enum CodingKeys: String, CodingKey {
        case applied
        case token
        case spans
        case anchor
        case anchorPos = "anchor_pos"
        case ids
    }
}

/// One rendered block, mirroring `BlockView` so its id is the same bs58 token
/// every other method takes and returns.
public struct Block: Codable, Sendable, Equatable {
    /// The block id every method takes as `block`. Opaque; pass it back unchanged.
    public var id: String
    /// The block type, as stored by `insert_block` or `set_kind`.
    public var kind: String
    /// Nesting depth, 0 for top level.
    public var depth: UInt32
    /// The block's attributes, such as `level` on a heading.
    public var attrs: [String: String]
    /// The block's text as runs of equally formatted characters, in order.
    public var spans: [Span]
    /// The id of each character of `spans`, in order.
    public var ids: [Run]

    public init(id: String, kind: String, depth: UInt32, attrs: [String: String], spans: [Span], ids: [Run]) {
        self.id = id
        self.kind = kind
        self.depth = depth
        self.attrs = attrs
        self.spans = spans
        self.ids = ids
    }
}

public struct BlockView: Codable, Sendable, Equatable {
    public var id: ContractTuple2<UInt64, UInt32>
    public var kind: String
    public var depth: UInt32
    public var attrs: [String: String]
    public var spans: [Span]

    public init(id: ContractTuple2<UInt64, UInt32>, kind: String, depth: UInt32, attrs: [String: String], spans: [Span]) {
        self.id = id
        self.kind = kind
        self.depth = depth
        self.attrs = attrs
        self.spans = spans
    }
}

/// One step of a text change, in Quill's delta shape: `{"retain": 6}`, `{"insert": "text"}` or `{"delete": 2}`.
/// A `retain` or `insert` step also carries `attributes`: an object of formatting, or `null` for none.
public indirect enum Change: Codable, Sendable, Equatable {
    /// Keeps `retain` characters, optionally changing their formatting.
    case retain(Change_Retain)
    /// Inserts text at the current position.
    case insert(Change_Insert)
    /// Removes characters at the current position.
    case delete(Change_Delete)

    public init(from decoder: any Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Change_Retain.self) {
            self = .retain(value)
            return
        }
        if let value = try? container.decode(Change_Insert.self) {
            self = .insert(value)
            return
        }
        if let value = try? container.decode(Change_Delete.self) {
            self = .delete(value)
            return
        }
        throw DecodingError.dataCorruptedError(in: container, debugDescription: "No Change variant matches")
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .retain(let value): try container.encode(value)
        case .insert(let value): try container.encode(value)
        case .delete(let value): try container.encode(value)
        }
    }
}

public struct Change_Delete: Codable, Sendable, Equatable {
    /// How many characters to remove.
    public var delete: UInt32

    public init(delete: UInt32) {
        self.delete = delete
    }
}

public struct Change_Insert: Codable, Sendable, Equatable {
    /// The text to insert.
