/// What `title_apply_delta_on` did; the title comes back either way.
public struct TitleApplied: Codable, Sendable, Equatable {
    /// `true` when the steps were written, `false` when the write was refused.
    public var applied: Bool
    /// The undo token for `title_undo`; `null` on a refusal.
    public var token: String?
    /// The title after the write, or the current title on a refusal.
    public var text: String
    /// The gap after this write's last change, or on a refusal the anchor sent.
    public var anchor: String?
    /// Where `anchor` sits in `text`.
    public var anchorPos: UInt32?
    /// The id of each character of `text`.
    public var ids: [Run]

    public init(applied: Bool, token: String? = nil, text: String, anchor: String? = nil, anchorPos: UInt32? = nil, ids: [Run]) {
        self.applied = applied
        self.token = token
        self.text = text
        self.anchor = anchor
        self.anchorPos = anchorPos
        self.ids = ids
    }

    enum CodingKeys: String, CodingKey {
        case applied
        case token
        case text
        case anchor
        case anchorPos = "anchor_pos"
        case ids
    }
}

/// The title with the id of each of its characters, in order.
public struct TitleState: Codable, Sendable, Equatable {
    /// The title text.
    public var text: String
    /// The id of each character of `text`, in order.
    public var ids: [Run]

    public init(text: String, ids: [Run]) {
        self.text = text
        self.ids = ids
    }
}

